public class Lesson {
    interface Builder {
        void build(int originX, int originZ);
    }

    static class TowerBuilder implements Builder {
        public void build(int originX, int originZ) {
            for (int y = 0; y < 4; y++) {
                Playground.placeBlock(originX, y, originZ, "stone_bricks");
            }
        }
    }

    static class PillarBuilder implements Builder {
        public void build(int originX, int originZ) {
            for (int y = 0; y < 2; y++) {
                Playground.placeBlock(originX, y, originZ, "oak_log");
            }
        }
    }

    public static void main(String[] args) {
        Builder[] builders = { new TowerBuilder(), new PillarBuilder() };
        int x = 2;
        for (Builder builder : builders) {
            builder.build(x, 0);
            x += 2;
        }
        Playground.say("Done building!");
    }
}
